import React, { useEffect, useState } from 'react';
import { FaceLivenessDetector } from '@aws-amplify/ui-react-liveness';
import { Loader, ThemeProvider } from '@aws-amplify/ui-react';
import { Amplify } from 'aws-amplify';
import '@aws-amplify/ui-react/styles.css';
import './App.css';

// ⚠️ FIXED CONFIGURATION FOR AMPLIFY V6 ⚠️
Amplify.configure({
  Auth: {
    Cognito: {
      identityPoolId: 'ap-northeast-1:4ad3569e-4c1a-4010-9f26-f1f0d96a7bec',
      region: 'ap-northeast-1',
      allowGuestAccess: true 
    }
  }
});

function App() {
  const [loading, setLoading] = useState(true);
  const [sessionId, setSessionId] = useState(null);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const id = params.get('session_id');

    if (id) {
      setSessionId(id);
      setLoading(false);
    } else {
      console.error("No session_id found in URL");
      setLoading(false);
    }
  }, []);

  // --- NEW: Auto-Click "Start Scanning" & Hide Warnings/Icons ---
  useEffect(() => {
    // 1. Force styles injection to hide unwanted elements
    const style = document.createElement('style');
    style.innerHTML = `
      /* Hide Header & Warnings */
      .amplify-liveness-instruction-overlay__header { display: none !important; }
      .amplify-alert { display: none !important; opacity: 0 !important; visibility: hidden !important; }
      [data-amplify-liveness-alert] { display: none !important; }
      
      /* Hide Recording Icon (Red Rec dot) */
      .amplify-liveness-recording-icon-container, 
      .amplify-liveness-recording-icon,
      [class*="recording-icon"] { 
        display: none !important; 
      }

      /* Hide Default Top-Right Close Button (Comprehensive selectors) */
      .amplify-liveness-close-button,
      .amplify-liveness-camera-module__close-button,
      [data-test-id="liveness-close-button"],
      button[aria-label="Close liveness check"],
      button[aria-label="Close"],
      .amplify-liveness-overlay__close-button,
      .amplify-liveness-header__close-button,
      button[class*="close"],
      button[class*="Close"],
      [class*="close-button"],
      [class*="CloseButton"],
      .amplify-button[aria-label*="close" i],
      .amplify-button[aria-label*="Close" i] {
        display: none !important;
        visibility: hidden !important;
        opacity: 0 !important;
        pointer-events: none !important;
      }
    `;
    document.head.appendChild(style);

    // 2. Auto-clicker for "Start Scanning" button
    const observer = new MutationObserver(() => {
      const buttons = document.querySelectorAll('button');
      buttons.forEach((btn) => {
        // Check for specific text or class usually found on that button
        if (btn.innerText.includes('Start Scanning') || btn.innerText.includes('Begin Check')) {
          console.log('Auto-clicking Start Scanning button...');
          btn.click();
        }
      });
    });

    // Start observing the DOM for the button
    observer.observe(document.body, { childList: true, subtree: true });

    return () => {
      observer.disconnect();
      document.head.removeChild(style);
    };
  }, []);

  const handleAnalysisComplete = async () => {
    console.log("Liveness Check Complete");
    if (window.FlutterChannel) {
      window.FlutterChannel.postMessage('COMPLETE');
    }
  };

  const handleError = (error) => {
    console.error(error);
    if (window.FlutterChannel) {
      window.FlutterChannel.postMessage('ERROR: ' + error.state);
    }
  };

  const handleCancel = () => {
    console.log("User canceled operation");
    if (window.FlutterChannel) {
      window.FlutterChannel.postMessage('CANCEL');
    } else {
      alert("Cancel clicked");
    }
  };

  if (loading) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', backgroundColor: 'white' }}>
        <Loader size="large" variation="linear" />
      </div>
    );
  }

  if (!sessionId) {
    return (
      <div style={{ height: '100vh', backgroundColor: 'white', color: 'black', display: 'flex', justifyContent: 'center', alignItems: 'center', flexDirection: 'column' }}>
        <p>Waiting for Session ID...</p>
        <p style={{ fontSize: '12px', color: '#666' }}>(If testing in browser, add ?session_id=test to URL)</p>
      </div>
    );
  }

  const customDisplayText = {
    instructionsHeaderText: 'Face Verification',
    instructionsMessageText: 'Please position your face in the oval.',
    startScreenBeginCheckText: 'Start Scanning',
  };

  const theme = {
    name: 'liveness-theme',
    tokens: {
      colors: {
        primary: {
          80: '#000000', 
          90: '#000000',
          100: '#000000',
        },
        background: {
          primary: '#ffffff',
        }
      },
    },
  };

  return (
    <ThemeProvider theme={theme}>
      <div style={{ width: '100vw', height: '100vh', backgroundColor: 'white', position: 'relative' }}>
        
        {/* --- Close Button (Top Left - Kept) --- */}
        <button
          onClick={handleCancel}
          style={{
            position: 'absolute',
            top: '20px',
            left: '20px',
            zIndex: 1000,
            background: 'rgba(0, 0, 0, 0.5)', 
            border: 'none',
            borderRadius: '50%',
            width: '40px',
            height: '40px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: 'white',
            fontSize: '20px',
            cursor: 'pointer',
            fontWeight: 'bold'
          }}
        >
          ✕
        </button>

        <FaceLivenessDetector
          sessionId={sessionId}
          region="ap-northeast-1"
          onAnalysisComplete={handleAnalysisComplete}
          onError={handleError}
          displayText={customDisplayText}
          disableInstructionScreen={true} 
        />
      </div>
    </ThemeProvider>
  );
}

export default App;